public sealed class RateCache
{
    private readonly List<Rate> _rates = [];

    // Looks read-only to callers, but it is the live list
    public IReadOnlyList<Rate> Rates => _rates;

    public void Refresh(IEnumerable<Rate> fresh)
    {
        _rates.Clear();         // compiles: readonly guards the field only
        _rates.AddRange(fresh); // a reader may see an empty list right now
    }
}

using System.Collections.Immutable;

public sealed class RateCache
{
    private ImmutableArray<Rate> _rates = [];

    // A snapshot: nobody can change it, not even this class
    public ImmutableArray<Rate> Rates => _rates;

    public void Refresh(IEnumerable<Rate> fresh)
    {
        _rates = [.. fresh]; // build a new snapshot, then publish it
    }
}
